<?php require 'config.php';if(!user()){header('Location: login.php');exit;} $id=(int)($_GET['room']??0);$st=$conn->prepare("SELECT * FROM rooms WHERE id=?");$st->bind_param("i",$id);$st->execute();$r=$st->get_result()->fetch_assoc();if(!$r)die('Room not found');$msg='';if($_SERVER['REQUEST_METHOD']=='POST'){$in=$_POST['check_in'];$out=$_POST['check_out'];$g=(int)$_POST['guests'];if(strtotime($out)<=strtotime($in))$msg='Check-out must be after check-in.';elseif(strtotime($in)<strtotime(date('Y-m-d'))) $msg='Choose a future arrival date.';else{$q=$conn->prepare("SELECT COUNT(*) n FROM bookings WHERE room_id=? AND status='Confirmed' AND check_in < ? AND check_out > ?");$q->bind_param("iss",$id,$out,$in);$q->execute();$n=$q->get_result()->fetch_assoc()['n'];if($n >= $r['quantity'])$msg='Room is not available for those dates.';else{$nights=(strtotime($out)-strtotime($in))/86400;$total=$nights*$r['price'];$u=user();$st=$conn->prepare("INSERT INTO bookings(user_id,room_id,name,email,phone,check_in,check_out,guests,total) VALUES(?,?,?,?,?,?,?,?,?)");$st->bind_param("iissssiid",$u['id'],$id,$u['name'],$u['email'],$u['phone'],$in,$out,$g,$total);$st->execute();header('Location: dashboard.php?booked=1');exit;}}}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Book Room</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="formpage"><div class="panel"><h1>Book <?=$r['type']?></h1><p>₹<?=number_format($r['price'])?> / night</p><?php if($msg):?><p class="error"><?=$msg?></p><?php endif;?><form method="post"><input name="check_in" type="date" required><input name="check_out" type="date" required><input name="guests" type="number" min="1" max="<?=$r['capacity']?>" value="2" required><div class="pay"><b>Demo secure payment</b><input placeholder="Card number" required><div class="two"><input placeholder="MM/YY" required><input placeholder="CVV" required></div></div><button class="btn">Confirm Booking & Pay</button></form><p><a href="index.php">Back</a></p></div></main></body></html>